static double noiseFromSpeed(double s) {
    if (s <= 0.3) return 0.01; // parado: ~1 m
    if (s <= walkSpeed) return 0.05; // andando: ~6 m
    if (s <= runSpeed) return 0.18; // correndo: ~22 m
    if (s <= vehicleSpeed) return 0.3; // correndo muito / bicicleta: ~36 m
    return 1.0;
  }
